-- Generated by `npm run catalog:import` against the live PokéAPI on 2026-10-13, then
-- reviewed before committing. Re-running the script and diffing its output is how the
-- catalog gets updated later (T-024: "política de atualização do catálogo") — paste
-- the new output into a fresh migration rather than editing this one.
on conflict (pokedex_number) do update set
  name = excluded.name,
  types = excluded.types,
  sprite_url = excluded.sprite_url,
  official_artwork_url = excluded.official_artwork_url,
  is_starter = excluded.is_starter,
  evolves_to_pokedex_number = excluded.evolves_to_pokedex_number,
  evolution_min_level = excluded.evolution_min_level,
  imported_at = now();
